// 站内原创分级阅读：每个主题包含多篇短文，正文、中文、重点单词和阅读理解均在本页完成。
Object.assign(ARTICLES[0],{zh:['Mia 是一名软件测试员。她打开登录页，输入邮箱和密码。登录按钮没有反应。Mia 发现了一个程序缺陷。','Mia 编写了一个测试用例，并把问题告诉开发人员。开发人员修复后，Mia 再次测试页面。现在按钮可以用了。']});
Object.assign(ARTICLES[1],{zh:['AI 助手可以帮助完成许多任务。你可以编写提示词，告诉 AI 你需要什么。清晰的提示词能帮助 AI 给出有用的回答。','测试人员可以让 AI 助手建议测试用例，但仍需检查答案，最终决定由人来做。']});
Object.assign(ARTICLES[2],{zh:['Leo 星期五预约了医生。他查看日程，预约时间是上午十点。','Leo 乘公交车，买了一张票并提前到达。看诊后，他保留了收据。']});
ARTICLES.push(
{id:'daily-coffee',topic:'DAILY ENGLISH',title:'A quiet morning at the café',level:'A1',minutes:3,paragraphs:['Nora walks to a small café before work. She orders tea and a sandwich. The server repeats the order, and Nora says, “That is right, thank you.”','She sits near the window and checks her schedule. At nine, she leaves for the office. The quiet morning helps her feel ready for the day.'],zh:['Nora 上班前走进一家小咖啡馆。她点了茶和三明治。服务员重复订单，Nora 说：“对的，谢谢。”','她坐在窗边查看日程。九点时，她离开去办公室。安静的早晨让她为一天做好准备。'],words:['order','repeat','schedule','ready'],question:'Why does Nora visit the café?',options:['To fix a server','To have breakfast before work','To buy a ticket'],answer:1,source:'English Lab 原创学习材料'},
{id:'daily-shopping',topic:'DAILY ENGLISH',title:'The receipt is useful',level:'A1',minutes:3,paragraphs:['Ben buys a lamp for his room. At home, he finds that the lamp does not work. He keeps the receipt and returns to the shop.','The shop assistant checks the lamp and gives Ben a new one. Ben tests it before he leaves. This time, the lamp works.'],zh:['Ben 为房间买了一盏灯。回家后，他发现灯不能用。他保留了收据并回到商店。','店员检查了灯，给 Ben 换了一盏新的。Ben 离开前先测试了一下，这次灯可以用了。'],words:['receipt','return','check','work'],question:'What helps Ben return the lamp?',options:['A receipt','A prompt','A password'],answer:0,source:'English Lab 原创学习材料'},
{id:'testing-report',topic:'SOFTWARE TESTING',title:'Writing a clear bug report',level:'A2',minutes:4,paragraphs:['A clear bug report helps the whole team. First, give the problem a short title. Then write the exact steps that caused it. Add the expected result and the actual result.','Screenshots can help, but words are still important. A developer should be able to repeat the problem. After the fix, the tester checks the same steps again.'],zh:['清晰的缺陷报告能帮助整个团队。先给问题写一个简短标题，再写出触发问题的准确步骤，并补充预期结果和实际结果。','截图会有帮助，但文字仍然重要。开发人员应该能够复现问题。修复之后，测试人员再次检查相同步骤。'],words:['bug','expected','actual','repeat'],question:'What should a developer be able to do?',options:['Buy a ticket','Repeat the problem','Change the requirement'],answer:1,source:'English Lab 原创学习材料'},
{id:'testing-regression',topic:'SOFTWARE TESTING',title:'Why regression testing matters',level:'A2',minutes:4,paragraphs:['A team fixes a payment bug. The payment button now works, but the change may affect another part of the app. The tester runs old test cases again.','This is regression testing. It checks that existing features still work after a change. The team finds a small problem in the receipt page and fixes it before release.'],zh:['团队修复了一个支付缺陷。支付按钮现在能用了，但这个改动可能影响应用的其他部分。测试人员再次运行旧测试用例。','这就是回归测试。它检查改动后已有功能是否仍然正常。团队发现收据页面的小问题，并在发布前修复。'],words:['regression testing','test case','feature','release'],question:'What does regression testing check?',options:['Only new colors','Existing features after a change','The office schedule'],answer:1,source:'English Lab 原创学习材料'},
{id:'computer-browser',topic:'COMPUTER & AI',title:'What happens when you open a website?',level:'A2',minutes:4,paragraphs:['You type an address into a browser. The browser sends a request to a server. The server finds the page and sends data back.','The browser reads the data and shows the page. Images may arrive after the text. If the network is slow, some parts take longer to appear.'],zh:['你在浏览器中输入地址，浏览器向服务器发送请求。服务器找到页面并把数据发回来。','浏览器读取数据并显示页面。图片可能比文字晚到；如果网络较慢，一些内容需要更久才会出现。'],words:['browser','request','server','network'],question:'Who sends data back to the browser?',options:['The server','The receipt','The schedule'],answer:0,source:'English Lab 原创学习材料'},
{id:'ai-review',topic:'COMPUTER & AI',title:'Use AI, then check the answer',level:'A2',minutes:4,paragraphs:['A tester asks an AI assistant to create test ideas. The prompt includes the feature, the user goal, and important limits. The assistant suggests several cases.','The tester reviews every suggestion. One case is useful, two need changes, and one is wrong. AI can save time, but a person remains responsible for the final decision.'],zh:['测试人员让 AI 助手创建测试思路。提示词包含功能、用户目标和重要限制。助手给出几个测试用例。','测试人员逐一检查建议：一个有用，两个需要修改，还有一个是错误的。AI 可以节省时间，但最终决定仍由人负责。'],words:['prompt','feature','review','decision'],question:'Who makes the final decision?',options:['The AI model alone','A person','The browser'],answer:1,source:'English Lab 原创学习材料'}
);

const readingTopicNames={'DAILY ENGLISH':'日常英语','SOFTWARE TESTING':'软件测试','COMPUTER & AI':'计算机与 AI'};
readingPage=function(){
  const article=ARTICLES.find(item=>item.id===articleId)||ARTICLES[0],topics=[...new Set(ARTICLES.map(item=>item.topic))];
  const body=article.paragraphs.map((paragraph,index)=>{let html=esc(paragraph);for(const name of article.words.slice().sort((a,b)=>b.length-a.length)){const re=new RegExp(`\\b(${name.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\$&')})\\b`,'gi');html=html.replace(re,`<button data-lookup="${esc(name)}">$1</button>`)}return `<p>${html}</p><p class="reading-zh">${esc(article.zh?.[index]||'')}</p>`}).join('');
  const catalog=topics.map(topic=>`<section class="reading-topic"><h3>${uiLanguage==='zh'?readingTopicNames[topic]:topic}</h3><div>${ARTICLES.filter(item=>item.topic===topic).map(item=>`<button class="reading-title ${item.id===article.id?'active':''}" data-article="${item.id}"><span>${esc(item.title)}</span><small>${item.level} · ${item.minutes} ${uiLanguage==='zh'?'分钟':'min'}</small></button>`).join('')}</div></section>`).join('');
  return `<div class="content reading-page">${head(uiLanguage==='zh'?'分级阅读':'READING ROOM',uiLanguage==='zh'?'短文精读':'Graded reading',uiLanguage==='zh'?'每个主题包含多篇短文；英文之后紧跟中文解释。':'Each topic contains several texts with guided reading.',`<span class="pill">${ARTICLES.length} ${uiLanguage==='zh'?'篇短文':'texts'}</span>`)}<section class="reading-library card">${catalog}</section><div class="two-col"><div><article class="card"><span class="tag">${uiLanguage==='zh'?readingTopicNames[article.topic]:article.topic}</span><h2 class="reading-title-main">${esc(article.title)}</h2><p class="muted-text">${esc(article.source)} · ${article.level} · ${article.minutes} ${uiLanguage==='zh'?'分钟':'min'}</p><div class="graded-reading-body">${body}</div><div class="action-row"><button class="primary" id="mark-read">${state.read.includes(article.id)?'✓ 再读一次':'标记已阅读并进入下一篇 →'}</button><button class="secondary" id="print">${uiLanguage==='zh'?'打印／保存 PDF':'Print / Save PDF'}</button></div></article><h2 class="section-heading">${uiLanguage==='zh'?'阅读理解':'Check your understanding'}</h2><section class="card"><h3>${esc(article.question)}</h3><div class="quiz-options">${article.options.map((option,index)=>`<button data-answer="${index}" class="${answerState===index?(index===article.answer?'correct':'wrong'):''}">${String.fromCharCode(65+index)}. ${esc(option)}</button>`).join('')}</div><p class="muted-text">${answerState===null?(uiLanguage==='zh'?'请选择一个答案。':'Choose one answer.'):answerState===article.answer?(uiLanguage==='zh'?'回答正确！+10 XP':'Correct! +10 XP'):(uiLanguage==='zh'?'再读一次短文后重试。':'Read once more and try again.')}</p></section></div><aside><section class="card"><div class="mini-title"><h3>${uiLanguage==='zh'?'重点单词':'Key words'}</h3><span>${uiLanguage==='zh'?'点击查看':'VIEW'}</span></div><div class="word-list">${article.words.map(name=>`<button data-lookup="${esc(name)}"><b>${esc(name)}</b><small>${uiLanguage==='zh'?'查看释义 →':'View →'}</small></button>`).join('')}</div></section></aside></div></div>`;
};

document.addEventListener('click',clickEvent=>{
  const button=clickEvent.target.closest('#mark-read');if(!button||page!=='reading')return;
  clickEvent.preventDefault();clickEvent.stopImmediatePropagation();
  const current=ARTICLES.find(item=>item.id===articleId)||ARTICLES[0];if(!state.read.includes(current.id))state.read.push(current.id);event('read',current.id);
  const sameTopic=ARTICLES.filter(item=>item.topic===current.topic),position=sameTopic.findIndex(item=>item.id===current.id);articleId=sameTopic[(position+1)%sameTopic.length].id;answerState=null;save();toast(uiLanguage==='zh'?'已记录，正在进入同主题下一篇':'Saved. Opening the next text.');render();window.scrollTo(0,0);
},true);
